function reload(){if(ammo[weapon]>=weaponDefs[weapon].clip||reserve[weapon]<=0||reloadTimer>0)return;reloadTimer=weapon===1?1.6:1.15;say('RELOADING…')}
function shoot(now){if(now-lastShot<weaponDefs[weapon].rate||reloadTimer>0)return;if(ammo[weapon]<=0){reload();return}lastShot=now;ammo[weapon]--;let wd=weaponDefs[weapon];let origin=camera.position.clone(),dir=new THREE.Vector3();camera.getWorldDirection(dir);let candidates=[];bots.forEach(b=>{if(!b.alive)return;let pos=b.mesh.position.clone().add(new THREE.Vector3(0,1,0)),to=pos.clone().sub(origin),along=to.dot(dir);if(along>0&&along<wd.range){let miss=to.addScaledVector(dir,-along).length();if(miss<(weapon===1?1.5:.85))candidates.push({b,along,miss})}});candidates.sort((a,b)=>a.along-b.along);if(candidates.length){let hit=candidates[0].b;hit.hp-=wd.damage*(weapon===1?(.72+Math.random()*.5):1);spark(hit.mesh.position.clone().add(new THREE.Vector3(0,1.3,0)),wd.color);if(hit.hp<=0){hit.alive=false;scene.remove(hit.mesh);elims++;resources.wood+=20;say('RIVAL ELIMINATED  +20 WOOD');spawnItem('shield',hit.x,hit.z);if(!bots.some(b=>b.alive))finish(true)}}else{let originP=player.position.clone().add(new THREE.Vector3(0,1.3,0));let tree=trees.find(t=>t.position.distanceTo(player.position)<4);if(tree){scene.remove(tree);trees.splice(trees.indexOf(tree),1);resources.wood+=15;say('+15 WOOD');}let sb=structures.find(s=>s.mesh.position.distanceTo(player.position)<6);if(sb){sb.hp-=wd.damage;if(sb.hp<=0){scene.remove(sb.mesh);structures.splice(structures.indexOf(sb),1);say('BUILD DESTROYED')}}}updateHud();}
