function interact(){let near=loot.filter(l=>!l.opened).sort((a,b)=>Math.hypot(a.x-player.position.x,a.z-player.position.z)-Math.hypot(b.x-player.position.x,b.z-player.position.z))[0];if(!near||Math.hypot(near.x-player.position.x,near.z-player.position.z)>4){say('NOTHING IN REACH');return}if(near.type==='chest'){near.opened=true;scene.remove(near.mesh);let roll=Math.random();if(roll<.55)spawnItem('gun',near.x+1,near.z,Math.floor(Math.random()*4));else if(roll<.78)spawnItem('shield',near.x+1,near.z);else spawnItem('heal',near.x+1,near.z);resources.wood+=Math.floor(8+Math.random()*10);say('CHEST OPENED · LOOT EJECTED');}else{near.opened=true;scene.remove(near.mesh);if(near.type==='gun'){selectWeapon(near.sub);ammo[weapon]=Math.min(weaponDefs[weapon].clip,ammo[weapon]+Math.ceil(weaponDefs[weapon].clip*.45));reserve[weapon]+=weaponDefs[weapon].clip;say(weaponDefs[weapon].name+' ACQUIRED')}else if(near.type==='shield'){shield=Math.min(100,shield+25);say('SHIELD +25')}else{health=Math.min(100,health+35);say('MEDKIT +35')}updateHud()}}
function placeBuild(){let type=['wall','floor','ramp','roof'][buildType],cost=type==='wall'?10:15;if(resources.wood<cost){say('NEED '+cost+' WOOD');return}resources.wood-=cost;let d=new THREE.Vector3(Math.sin(yaw),0,Math.cos(yaw)),x=player.position.x+d.x*3,z=player.position.z+d.z*3,y=height(x,z);let g=new THREE.Group(),material=[woodmat,stoneMat,metalMat][buildMat];if(type==='wall')box(g,0,1.4,0,3.8,2.8,.25,material);if(type==='floor')box(g,0,.15,0,3.8,.3,3.8,material);if(type==='ramp'){let o=box(g,0,.85,0,3.8,.28,4,material);o.rotation.x=-.42}if(type==='roof'){let o=box(g,0,1.3,0,3.8,.22,3.8,material);o.rotation.x=.45}g.position.set(Math.round(x/3)*3,y,Math.round(z/3)*3);g.rotation.y=yaw;g.traverse(o=>{if(o.isMesh){o.castShadow=true;o.receiveShadow=true;o.userData.building=true}});scene.add(g);structures.push({mesh:g,hp:buildMat===0?100:buildMat===1?220:350});updateHud();say(type.toUpperCase()+' PLACED · '+(buildMat===0?'WOOD':buildMat===1?'STONE':'METAL'))}
function takeDamage(amount){if(shield>0){let s=Math.min(shield,amount);shield-=s;amount-=s}health=Math.max(0,health-amount);enemyDamageFlash=.3;updateHud();if(health<=0)finish(false)}
