function finish(win){if(matchEnd)return;matchEnd=true;document.exitPointerLock?.();$('#result').style.display='flex';$('#resultEyebrow').textContent=win?'ISLAND CHAMPION':'MATCH COMPLETE';$('#resultTitle').innerHTML=win?'VICTORY<span>!</span>':'ELIMINATED';$('#resultDesc').textContent=win?'The island is yours. A flawless storm survivor.':'The storm claimed another. Drop back in and try again.';$('#resultStats').textContent=`${elims} ELIMINATIONS　·　${Math.max(1,1+bots.filter(b=>b.alive).length)}TH PLACE`}
// shrinking storm ring
const ringGeo=new THREE.BufferGeometry(),ringPts=[];for(let i=0;i<=180;i++){let a=i/180*Math.PI*2;ringPts.push(new THREE.Vector3(Math.cos(a),.22,Math.sin(a)))}ringGeo.setFromPoints(ringPts);let ring=new THREE.Line(ringGeo,new THREE.LineBasicMaterial({color:0x9a6cff,transparent:true,opacity:.88}));scene.add(ring);
const stormWall=new THREE.Mesh(new THREE.CylinderGeometry(1,1,18,96,1,true),new THREE.MeshBasicMaterial({color:0x8570ff,transparent:true,opacity:.09,side:THREE.DoubleSide}));scene.add(stormWall);
function updateStorm(dt){if(!matchStarted||matchEnd)return;stormTimer-=dt;if(stormTimer<=0){stormPhase++;stormTimer=stormPhase===1?85:stormPhase===2?65:45;stormRadius=Math.max(22,stormRadius*.72);stormCenter.set(Math.sin(stormPhase*2.7)*25,Math.cos(stormPhase*1.9)*25);say('STORM CIRCLE IS CLOSING');if(stormPhase>5)stormTimer=45}ring.position.set(stormCenter.x,.25,stormCenter.y);ring.scale.set(stormRadius,1,stormRadius);stormWall.position.set(stormCenter.x,8,stormCenter.y);stormWall.scale.set(stormRadius,1,stormRadius);let d=Math.hypot(player.position.x-stormCenter.x,player.position.z-stormCenter.y);$('#phase').textContent=d>stormRadius?'⚠ OUTSIDE SAFE ZONE':'SAFE ZONE · PHASE '+(stormPhase+1);$('#stormText').textContent=(d>stormRadius?'STORM DAMAGE · ':'STORM IN ')+formatTime(stormTimer);if(d>stormRadius){stormDmg+=dt;if(stormDmg>1){stormDmg=0;takeDamage(4+stormPhase*1.5)}}bots.forEach(b=>{if(b.alive&&Math.hypot(b.x-stormCenter.x,b.z-stormCenter.y)>stormRadius){b.hp-=dt*4;if(b.hp<=0){b.alive=false;scene.remove(b.mesh)}}})}
let stormDmg=0;function formatTime(s){let m=Math.floor(s/60),sec=Math.floor(s%60);return`0${m}:${('0'+sec).slice(-2)}`}
function updateBots(dt){if(!matchStarted||matchEnd)return;bots.forEach(b=>{if(!b.alive)return;let dx=player.position.x-b.x,dz=player.position.z-b.z,dist=Math.hypot(dx,dz);b.think-=dt;if(dist<34){b.mesh.rotation.y=Math.atan2(dx,dz);if(dist>8){b.x+=dx/dist*dt*(dist>18?2.5:1.2);b.z+=dz/dist*dt*(dist>18?2.5:1.2)}b.fire-=dt;if(b.fire<=0&&dist<31){b.fire=1.5+Math.random()*1.8;if(Math.random()<.42)takeDamage(5+Math.random()*6)}}else{if(b.think<=0){b.think=2+Math.random()*3;b.way=Math.random()*Math.PI*2}b.x+=Math.sin(b.way)*dt*1.15;b.z+=Math.cos(b.way)*dt*1.15;b.mesh.rotation.y=b.way}b.x=Math.max(-140,Math.min(140,b.x));b.z=Math.max(-140,Math.min(140,b.z));b.mesh.position.set(b.x,height(b.x,b.z),b.z);b.mesh.position.y+=Math.abs(Math.sin(clock*5+b.x))*.045});updateHud()}
function nearestLoot(){let near=loot.filter(l=>!l.opened).sort((a,b)=>Math.hypot(a.x-player.position.x,a.z-player.position.z)-Math.hypot(b.x-player.position.x,b.z-player.position.z))[0];if(near&&Math.hypot(near.x-player.position.x,near.z-player.position.z)<4){$('#hint').style.display='block';$('#hint').textContent=`[ E ] ${near.type==='chest'?'OPEN SUPPLY CHEST':'PICK UP '+(near.type==='gun'?weaponDefs[near.sub].name:near.type.toUpperCase())}`}else $('#hint').style.display='none'}
