=dt;document.body.style.filter='brightness(1.16)';if(enemyDamageFlash<=0)document.body.style.filter=''}let angle=((yaw*180/Math.PI)%360+360)%360,dirs=['N','NE','E','SE','S','SW','W','NW'];$('#compass').textContent=dirs[Math.round(angle/45)%8]+' · '+String(Math.round(angle)).padStart(3,'0')+'°';drawMap()}else{let t=clock3.elapsedTime;camera.position.lerp(new THREE.Vector3(Math.sin(t*.09)*100,62,Math.cos(t*.09)*100),.012);camera.lookAt(0,0,0);loot.forEach(l=>{if(l.type==='chest')l.mesh.rotation.y+=dt*.15})}renderer.render(scene,camera)}frame();
